// ===== 설정 (여기만 수정하세요) =====
return [{ json: {
  API_KEY: 'AIzaSyDI0pjUJBjW2zorcIDkL7G1LCsd21gNmNQ',
  // LG 공식 채널: 이 영상들이 속한 채널의 영상 전체에서 댓글·LG 답변을 모읍니다.
  // 기본값 = LG전자서비스 공식 채널(1차 수집에서 LG 답변이 가장 많던 채널)의 영상 1개
  SEED_VIDEO_IDS: ['wUWv0xFiDrA'],
  // 영상 주인 채널 외에 'LG 공식 답변'으로 볼 채널 ID (UC...로 시작). 모르면 비워 두세요.
  EXTRA_OFFICIAL_CHANNEL_IDS: [],
  AIRCON_ONLY: true,          // true: 에어컨·ThinQ 관련 영상만 / false: 채널 영상 전체
  MAX_VIDEOS: 400,            // 댓글을 가져올 영상 최대 수
} }];

// 시드 영상 → 공식 채널 ID와 '업로드 전체' 재생목록 ID
const cfg = $('설정').first().json;
const map = new Map();
for (const item of $input.all()) for (const v of (item.json.items || [])) {
  const sn = v.snippet || {}, ch = sn.channelId;
  if (ch && ch.startsWith('UC') && !map.has(ch)) map.set(ch, { playlistId: 'UU' + ch.slice(2), channelId: ch, channel: sn.channelTitle || '' });
}
const out = [...map.values()].map(j => ({ json: { ...j, apiKey: cfg.API_KEY } }));
return out.length ? out : [{ json: { playlistId: 'NONE', apiKey: cfg.API_KEY } }];

// 채널 영상 중 에어컨·ThinQ 관련만 골라 댓글 요청 목록 만들기
const cfg = $('설정').first().json;
const RE = /에어컨|에어콘|휘센|whisen|냉방|냉난방|실외기|실내기|씽큐|thinq|스마트\s*진단|자가\s*진단|제습|시스템\s*에어/i;
const seen = new Set(), out = [];
for (const item of $input.all()) for (const p of (item.json.items || [])) {
  const sn = p.snippet || {}, id = (sn.resourceId || {}).videoId;
  if (!id || seen.has(id)) continue;
  if (cfg.AIRCON_ONLY && !RE.test((sn.title || '') + ' ' + (sn.description || '').slice(0, 300))) continue;
  seen.add(id);
  out.push({ json: { videoId: id, videoTitle: sn.title, channel: sn.channelTitle || '', publishedAt: String(sn.publishedAt || '').slice(0, 10), apiKey: cfg.API_KEY } });
}
return out.slice(0, cfg.MAX_VIDEOS);

// 답글이 5개를 넘어 일부만 온 스레드 → 전체 답글 추가 요청 목록
const cfg = $('설정').first().json;
const out = [];
for (const item of $input.all()) for (const t of (item.json.items || [])) {
  const s = t.snippet || {}, got = ((t.replies || {}).comments || []).length;
  if ((s.totalReplyCount || 0) > got) out.push({ json: { parentId: t.id, apiKey: cfg.API_KEY } });
}
return out.length ? out : [{ json: { parentId: 'NONE', apiKey: cfg.API_KEY } }];

// 스레드별 정리: 고객 댓글 → LG 공식 답변 → 이후 고객 반응
const cfg = $('설정').first().json;
const official = new Set([...($('업로드 목록 ID').all().map(i => i.json.channelId).filter(Boolean)), ...(cfg.EXTRA_OFFICIAL_CHANNEL_IDS || [])]);
const videos = new Map($('영상 고르기').all().map(i => [i.json.videoId, i.json]));
// 추가로 받은 전체 답글 (parentId별)
const full = new Map();
for (const item of $input.all()) for (const c of (item.json.items || [])) {
  const pid = (c.snippet || {}).parentId; if (!pid) continue;
  if (!full.has(pid)) full.set(pid, []); full.get(pid).push(c);
}
const clean = s => String(s || '').replace(/\s+/g, ' ').trim();
const day = s => String(s || '').slice(0, 10);
const author = sn => ((sn || {}).authorChannelId || {}).value || '';
const SYMPTOMS = { '냉방불량': /찬\s*바람이?\s*안|안\s*시원|시원하지\s*않|냉방이?\s*(약|안)|미지근/, '냄새': /냄새|쉰내|곰팡/, '물샘': /물이?\s*(새|샘|떨어)|누수|배수/,
  '소음': /소음|시끄|소리/, '에러코드': /CH\s?-?\d{1,3}|에러|오류\s*코드/i, '작동이상': /꺼져|꺼짐|안\s*켜|안\s*돌|작동\s*(이\s*)?안|멈춰|깜빡/,
  '청소·필터': /청소|필터|세척|건조/, '리모컨·앱': /리모컨|리모콘|씽큐|thinq|앱|어플/i, '설치': /설치|배관|실외기\s*위치/ };
const TYPE = { '고객센터·서비스 안내': /1544|1577|고객\s*센터|서비스\s*센터|상담\s*센터|서비스\s*접수|상담을|점검을\s*받|전문\s*(매니저|상담)/, '링크 안내': /https?:\/\/|lge\.co\.kr|lgq\.kr/,
  '원인 설명': /원인|때문|경우|발생(할|하|될)|으로\s*인해|수\s*있습니다/, '조치 방법 안내': /해\s*(주세요|보세요|보시|주시)|확인해|눌러|청소|리셋|차단기|분리|건조|교체|설정/, '사과': /죄송|불편을\s*드려|양해/ };
const REACT = { '해결됨': /해결|됐어요|되네요|됩니다|되었|고쳤|작동\s*(해|하네|돼)|성공/, '여전히 안 됨': /안\s*(돼|되|됨|나와)|그래도|여전히|똑같|마찬가지|소용\s*없|해봤|했는데/, '추가 질문': /\?|나요|까요|가요|어떻게|어디/, '감사 인사': /감사|고맙/ };
const tags = (t, M) => Object.entries(M).filter(([, re]) => re.test(t)).map(([k]) => k).join(', ');
const norm = t => t.replace(/^[^,]{1,30}님[,\s]*/, '').replace(/https?:\/\/\S+/g, '[링크]').replace(/\d+/g, '#').slice(0, 60);

const rows = [];
for (const item of $('댓글 스레드').all()) for (const t of (item.json.items || [])) {
  const s = t.snippet || {}, top = (s.topLevelComment || {}).snippet || {};
  if (official.has(author(top))) continue;                       // LG가 직접 쓴 최상위 댓글은 제외
  const custId = author(top);
  const replies = (full.get(t.id) || (t.replies || {}).comments || []).map(c => c.snippet || {})
    .sort((a, b) => String(a.publishedAt).localeCompare(String(b.publishedAt)));
  const lg = replies.filter(r => official.has(author(r)));
  const firstLg = lg[0];
  const after = firstLg ? replies.filter(r => String(r.publishedAt) > String(firstLg.publishedAt) && !official.has(author(r))) : [];
  const custAfter = after.filter(r => custId && author(r) === custId).map(r => clean(r.textOriginal || r.textDisplay));
  const text = clean(top.textOriginal || top.textDisplay);
  const lgText = lg.map(r => clean(r.textOriginal || r.textDisplay)).join(' / ');
  const days = firstLg ? Math.round((new Date(firstLg.publishedAt) - new Date(top.publishedAt)) / 864e5) : '';
  const v = videos.get(s.videoId) || {};
  rows.push({ json: {
    '영상제목': v.videoTitle || '', '영상URL': `https://www.youtube.com/watch?v=${s.videoId}`, '댓글URL': `https://www.youtube.com/watch?v=${s.videoId}&lc=${t.id}`,
    '고객 댓글': text, '고객 댓글 작성일': day(top.publishedAt), '좋아요': top.likeCount || 0,
    '증상분류': tags(text, SYMPTOMS), '질문형': /\?|나요|까요|가요|어떻게|왜/.test(text) ? 'Y' : '',
    'LG 답변 여부': firstLg ? 'Y' : '', 'LG 답변 내용': lgText, 'LG 첫 답변일': firstLg ? day(firstLg.publishedAt) : '', '답변까지 걸린 일수': days,
    'LG 답변 수': lg.length, '답변 유형': firstLg ? tags(lgText, TYPE) : '', '답변 문구 키(템플릿 비교용)': firstLg ? norm(clean(firstLg.textOriginal || firstLg.textDisplay)) : '',
    '고객 후속 답글': custAfter.join(' / '), '고객 후속 반응': custAfter.length ? (tags(custAfter.join(' '), REACT) || '기타') : (firstLg ? '반응 없음' : ''),
    '다른 사람 답글 수': replies.filter(r => !official.has(author(r)) && author(r) !== custId).length, '스레드ID': t.id,
  } });
}
// 같은 답변 문구가 몇 번 쓰였는지 (복사·붙여넣기 정도)
const cnt = new Map(); for (const r of rows) { const k = r.json['답변 문구 키(템플릿 비교용)']; if (k) cnt.set(k, (cnt.get(k) || 0) + 1); }
for (const r of rows) { const k = r.json['답변 문구 키(템플릿 비교용)']; r.json['같은 문구 사용 횟수'] = k ? cnt.get(k) : ''; }
rows.sort((a, b) => (b.json['LG 답변 여부'] === 'Y') - (a.json['LG 답변 여부'] === 'Y') || String(b.json['고객 댓글 작성일']).localeCompare(String(a.json['고객 댓글 작성일'])));
return rows;

// 요약표: 답변률, 응답 시간, 답변 유형, 고객 후속 반응, 자주 쓰인 답변 문구
const rows = $input.all().map(i => i.json);
const ans = rows.filter(r => r['LG 답변 여부'] === 'Y');
const pct = (a, b) => b ? Math.round(a / b * 1000) / 10 + '%' : '-';
const out = [];
const add = (구분, 항목, 값, 비율 = '') => out.push({ json: { 구분, 항목, 값, 비율 } });
add('기본', '고객 댓글(스레드) 수', rows.length);
add('기본', 'LG 공식 답변이 달린 댓글', ans.length, pct(ans.length, rows.length));
const q = rows.filter(r => r['질문형'] === 'Y'); add('기본', '질문형 댓글 중 LG 답변 비율', q.filter(r => r['LG 답변 여부'] === 'Y').length, pct(q.filter(r => r['LG 답변 여부'] === 'Y').length, q.length));
const d = ans.map(r => Number(r['답변까지 걸린 일수'])).filter(n => !isNaN(n)).sort((a, b) => a - b);
add('응답 시간', '중앙값(일)', d.length ? d[Math.floor(d.length / 2)] : '-'); add('응답 시간', '7일 이내 답변', d.filter(n => n <= 7).length, pct(d.filter(n => n <= 7).length, d.length));
for (const t of ['고객센터·서비스 안내', '링크 안내', '원인 설명', '조치 방법 안내', '사과']) { const c = ans.filter(r => r['답변 유형'].includes(t)).length; add('답변 유형(중복)', t, c, pct(c, ans.length)); }
const onlyCs = ans.filter(r => r['답변 유형'].includes('고객센터·서비스 안내') && !r['답변 유형'].includes('원인 설명') && !r['답변 유형'].includes('조치 방법 안내')).length;
add('답변 유형(중복)', '원인·조치 없이 고객센터만 안내', onlyCs, pct(onlyCs, ans.length));
for (const t of ['해결됨', '여전히 안 됨', '추가 질문', '감사 인사', '기타', '반응 없음']) { const c = ans.filter(r => r['고객 후속 반응'].includes(t)).length; add('고객 후속 반응(중복)', t, c, pct(c, ans.length)); }
const rep = ans.filter(r => Number(r['같은 문구 사용 횟수']) >= 3).length; add('템플릿', '3번 이상 쓰인 같은 문구로 시작하는 답변', rep, pct(rep, ans.length));
const cnt = new Map(); for (const r of ans) { const k = r['답변 문구 키(템플릿 비교용)']; cnt.set(k, (cnt.get(k) || 0) + 1); }
[...cnt].sort((a, b) => b[1] - a[1]).slice(0, 15).forEach(([k, n], i) => add('자주 쓰인 답변 문구', `${i + 1}위: ${k}`, n, pct(n, ans.length)));
return out;
